        elif name == OUTCOME_QUEUE_ITEM_PROCESSED and not has_process:
            outcomes[name] = {"status": "failed", "reason": "hollow queue"}
        elif name == OUTCOME_REFUSED_ACTION_ERRORS and always_200:
